/**
 * Product-only elegant menswear seed.
 *
 * Supabase remains the live source when available, while this reviewed seed
 * ensures the shop stays useful offline and before a catalog publish. It is
 * generated by scripts/expand-elegant-menswear.js.
 */

import type { ShopCatalogItem } from '../src/types/shop';

// JSON is required lazily by useShopCatalog, keeping it off the startup path.
// eslint-disable-next-line @typescript-eslint/no-var-requires
const ELEGANT_MENSWEAR_CATALOG = require('./shop_catalog_elegant_international.json') as Array<{
    id: string;
    brand: string;
    name: string;
    price: number;
    currency?: string;
    image_url: string;
    garment_type: ShopCatalogItem['garmentType'];
    description?: string;
    source_url?: string;
}>;

export type { ShopCatalogItem };

export interface ShopCategory {
    key: string;
    label: string;
}

export const SHOP_CATEGORIES: ShopCategory[] = [
    { key: 'all', label: 'All' },
    { key: 'outfits', label: 'Outfits' },
    { key: 'upper_body', label: 'Tops' },
    { key: 'lower_body', label: 'Bottoms' },
    { key: 'shoes', label: 'Shoes' },
    { key: 'accessory', label: 'Accessories' },
];

export const SHOP_CATALOG_ITEMS: ShopCatalogItem[] = ELEGANT_MENSWEAR_CATALOG.map((item) => ({
    id: item.id,
    brand: item.brand,
    name: item.name,
    price: Number(item.price),
    currency: item.currency,
    imageUrl: item.image_url,
    garmentType: item.garment_type,
    description: item.description,
    sourceUrl: item.source_url,
}));

export const SHOP_BRANDS = ['All', ...[...new Set(SHOP_CATALOG_ITEMS.map((item) => item.brand))].sort((a, b) => a.localeCompare(b))];

export const SHOP_OUTFITS: ShopCatalogItem[] = SHOP_CATALOG_ITEMS.filter((item) => item.garmentType === 'outfit');
